# METADATA
# title: ÖPUL 2023 – Herbizidverzicht Wein, Obst und Hopfen (o6_11) – Grundlagen
# description: >-
#   Gemeinsame Hilfsregeln: Antragsjahr, Teilnahme an Maßnahme 11,
#   Klassifizierung von Wein-, Obst- und Hopfenflächen.
package oepul.o6_11

cfg := data.o6_11

measure_id := "11"

year := input.farm.year

parcels := object.get(input, ["land", "parcels"], [])

oepul_measures := object.get(input, ["farm", "oepul", "measures"], [])

# Teilnahmeeintrag der Maßnahme 11 (erster Eintrag, falls mehrfach angegeben)
participations := [m | some m in oepul_measures; m.measure_id == measure_id]

participates if count(participations) > 0

participation := participations[0] if participates

contract_start_year := participation.contract_start_year

# Weitere Maßnahmen des Betriebes (Maßnahmen-IDs gemäß SRL, z. B. "1A", "1B", "12")
farm_measure_ids contains m.measure_id if {
	some m in oepul_measures
}

year_of(date_string) := to_number(substring(date_string, 0, 4))

# ---------------------------------------------------------------------------
# Nutzungsart je Schlag (Rule O611-ELIG-CROPS, O611-SCHNITTWEIN-COUNTS,
# O611-REBSCHULE-EXCL)
# ---------------------------------------------------------------------------
usage_type_rows := {row.usage_type: row | some row in cfg.usage_types}

default_usage_by_category := {row.default_for_crop_category: row.usage_type |
	some row in cfg.usage_types
	row.default_for_crop_category != null
}

parcel_usage_type(p) := p.crop.usage_type if {
	p.crop.usage_type != null
} else := default_usage_by_category[p.crop.crop_category] if {
	default_usage_by_category[p.crop.crop_category]
} else := "not_wine_fruit_hop"

parcel_usage_row(p) := usage_type_rows[parcel_usage_type(p)]

parcel_area(p) := object.get(p, "area_ha", 0)

parcel_species(p) := object.get(p, ["crop", "crop_name"], null)

# Obstarten gemäß Definition (Rule O611-DEF-OBST); ab 2025 zusätzliche Arten
fruit_species_valid(species) if {
	species in cfg.fruit_crops.base
}

fruit_species_valid(species) if {
	some row in cfg.fruit_crops.from_2025
	row.species == species
	year >= row.valid_from_year
}

# Obstfläche: Art unbekannt (null) -> als Obst gemäß Nutzungsart behandelt
fruit_species_ok(p) if parcel_species(p) == null

fruit_species_ok(p) if fruit_species_valid(parcel_species(p))

# Wein-, Obst- oder Hopfenfläche im Sinne der Maßnahme
is_wfh_parcel(p) if {
	row := parcel_usage_row(p)
	row.is_wine_fruit_hop_area
	row.usage_type != "fruit"
}

is_wfh_parcel(p) if {
	parcel_usage_type(p) == "fruit"
	fruit_species_ok(p)
}

# Herbizidverzicht gilt für die gesamte Wein-, Obst- und Hopfenfläche
# des Betriebes (inkl. Schnittweingärten, nicht für Rebschulen)
herbicide_ban_parcel(p) if {
	is_wfh_parcel(p)
	parcel_usage_row(p).herbicide_ban_applies
}

# Fläche, die für die Mindestteilnahmefläche zählt (Rule O611-MIN-AREA)
counts_for_minimum_area(p) if {
	is_wfh_parcel(p)
	parcel_usage_row(p).counts_for_minimum_area
}

wfh_parcel_ids contains p.parcel_id if {
	some p in parcels
	is_wfh_parcel(p)
}

herbicide_ban_parcel_ids contains p.parcel_id if {
	some p in parcels
	herbicide_ban_parcel(p)
}

# Kulturen, die nicht dem Herbizidverzicht unterliegen (für Rule O611-PURCHASE-OTHER-CROPS)
non_wfh_crop_categories contains p.crop.crop_category if {
	some p in parcels
	not herbicide_ban_parcel(p)
}

# o6_11 policy module
# o6_11 – Gesamtentscheidung
# Aggregation aller Verstöße, Hinweise und der Prämienberechnung.
package oepul.o6_11

violations contains {"rule_id": "O611-CONTRACT-PERIOD", "message": "Vertragsbeginn nur am 01.01.2023, 01.01.2024 oder 01.01.2025 möglich"} if {
	participates
	not contract_start_valid
}

violations contains {"rule_id": "O611-LAST-ENTRY", "message": "Letzter Einstieg mit Förderjahr 2025 (Antrag bis 31.12.2024)"} if entry_after_last_entry_year

violations contains {"rule_id": "O611-APPLY-DEADLINE", "message": "Maßnahmenantrag nicht bis 31.12. vor Vertragsbeginn gestellt"} if application_late

violations contains {"rule_id": "O611-MIN-AREA", "message": sprintf("Mindestteilnahmefläche 0,5 ha nicht erreicht (%.2f ha)", [minimum_area_ha])} if minimum_area_violation

violations contains {"rule_id": "O611-GEN-MIN-FARM-SIZE", "message": "Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr nicht erreicht"} if farm_min_size_violation

violations contains {"rule_id": "O611-GEN-APPLICANT", "message": msg} if {
	some msg in applicant_violations
}

violations contains {"rule_id": "O611-COMB-BIO", "message": "Betriebliche Kombination mit Biologischer Wirtschaftsweise ausgeschlossen (außer Bio-Teilbetrieb Acker/Grünland)"} if organic_combination_conflict

violations contains {"rule_id": "O611-SWITCH-BIO", "message": "Umstieg in Biologische Wirtschaftsweise nur bis 31.12.2025 möglich"} if switch_to_organic_too_late

violations contains {"rule_id": "O611-COMB-PARCEL", "parcel_id": c.parcel_id, "message": sprintf("Maßnahme 11 ist mit Maßnahme %s auf der Einzelfläche nicht kombinierbar", [c.other_measure])} if {
	some c in parcel_combination_conflicts
}

violations contains {"rule_id": herbicide_rule_id(v.zone), "parcel_id": v.parcel_id, "message": sprintf("Herbizideinsatz (%v, Bereich %v) im Vertragszeitraum", [v.product, v.zone])} if {
	some v in herbicide_ban_violations
}

violations contains {"rule_id": "O611-AMEISENSAEURE", "parcel_id": v.parcel_id, "message": "Einsatz von Ameisensäure (nicht genehmigter Wirkstoff)"} if {
	some v in formic_acid_violations
}

violations contains {"rule_id": "O611-PURCHASE-STORAGE", "message": sprintf("%v: %s", [v.product, v.reason])} if {
	some v in purchase_storage_violations
}

violations contains {"rule_id": "O611-PSM-CODE-REQ", "parcel_id": m.parcel_id, "message": sprintf("PSM-Code %s im Mehrfachantrag fehlt", [m.code])} if {
	some m in missing_psm_codes
}

violations contains {"rule_id": "O611-GEN-OP-CODE", "parcel_id": m.parcel_id, "message": sprintf("Code OP bzw. maßnahmenbezogener OP-Code fehlt (Fälle: %v)", [m.cases])} if {
	some m in missing_op_codes
}

violations contains {"rule_id": "O611-GEN-TAKEOVER", "message": msg} if {
	some msg in takeover_violations
}

violations contains {"rule_id": "O611-GEN-CONTROL-REFUSAL", "message": "Verweigerung der Vor-Ort-Kontrolle: Antrag abzulehnen, Verträge zu beenden und rückabzuwickeln"} if inspection_refused

notices contains {"rule_id": "O611-COMB-PARCEL", "parcel_id": c.parcel_id, "message": sprintf("Kombination mit Maßnahme %s nur gemäß Fußnote %s des Anhangs L", [c.other_measure, c.footnote])} if {
	some c in parcel_combination_limited
}

notices contains {"rule_id": "O611-GEN-CAP", "parcel_id": pid, "message": "Prämienobergrenze für Flächenzahlungen überschritten; Prämie wurde anteilig gekürzt"} if {
	some pid in payment_cap_exceeded_parcels
}

notices contains {"rule_id": "O611-GEN-MIN-PAYOUT", "message": "Auszahlungsbetrag bis 50 Euro – von der Gewährung kann abgesehen werden"} if {
	participates
	payout_may_be_withheld
}

notices contains {"rule_id": "O611-GEN-EXIT-REPAYMENT", "message": "Ausstieg vor Ende des Vertragszeitraumes: bereits gewährte Prämien sind zurückzuzahlen"} if exit_repayment_required

notices contains {"rule_id": "O611-GEN-MISSED-PAYMENT-CLAIM", "message": "Zahlungsantrag mehr als 1 Jahr versäumt: Verpflichtung endet, bisherige Prämien sind zurückzuzahlen"} if payment_claim_overdue

notices contains {"rule_id": "O611-GEN-FORCE-MAJEURE", "message": "Besonderer Umstand nicht gemeldet: Rückforderung kann nicht abgewendet werden"} if count(unreported_circumstances) > 0

notices contains {"rule_id": "O611-PSM-CODE-2026-ABOLISHED", "message": "Ab Antragsjahr 2026 ist keine PSM-Codierung im Mehrfachantrag mehr erforderlich"} if {
	participates
	not psm_coding_required_year
}

parcel_results[p.parcel_id] := {
	"wine_fruit_hop_area": wfh_parcel_bool(p),
	"herbicide_ban_applies": herbicide_ban_parcel_bool(p),
	"premium_eligible": parcel_premium_eligible_bool(p),
	"no_premium_reasons": parcel_no_premium_reasons(p),
	"premium_gross_eur": object.get(parcel_premium, p.parcel_id, 0),
	"premium_payable_eur": object.get(parcel_payable, p.parcel_id, 0),
} if {
	some p in parcels
}

herbicide_ban_parcel_bool(p) if herbicide_ban_parcel(p)

herbicide_ban_parcel_bool(p) := false if not herbicide_ban_parcel(p)

parcel_premium_eligible_bool(p) if parcel_premium_eligible(p)

parcel_premium_eligible_bool(p) := false if not parcel_premium_eligible(p)

compliant if {
	participates
	count(violations) == 0
}

decision := {
	"measure": "o6_11",
	"year": year,
	"participates": participates_bool,
	"contract_valid": contract_valid_bool,
	"compliant": compliant_bool,
	"access_condition_failures": access_condition_failures,
	"premium_withheld_reasons": premium_withheld_reasons,
	"premium_eligible_area_ha": premium_eligible_area_ha,
	"premium_before_modulation_eur": premium_before_modulation,
	"modulation_factor": modulation_factor,
	"premium_after_sanction_eur": premium_after_sanction,
	"premium_after_modulation_eur": premium_after_modulation,
	"advance_payment_max_eur": advance_payment_max_eur,
	"reduction_order": reduction_order,
	"sanction_reduction_percent": sanction_reduction_percent,
	"premium_payable_eur": premium_payable,
	"exit_repayment_required": exit_repayment_required_bool,
	"violations": violations,
	"notices": notices,
	"parcels": parcel_results,
}

compliant_bool if compliant

compliant_bool := false if not compliant

exit_repayment_required_bool if exit_repayment_required

exit_repayment_required_bool := false if not exit_repayment_required

participates_bool if participates

participates_bool := false if not participates

contract_valid_bool if {
	participates
	not no_contract
}

contract_valid_bool := false if not participates

contract_valid_bool := false if no_contract

wfh_parcel_bool(p) if is_wfh_parcel(p)

wfh_parcel_bool(p) := false if not is_wfh_parcel(p)

# Zaunbereich (Rule O611-FENCE) bzw. Stammbehandlung (Rule O611-STAMM)
herbicide_rule_id(zone) := "O611-FENCE" if zone == "fence_line"

herbicide_rule_id(zone) := "O611-STAMM" if zone == "stem"

herbicide_rule_id(zone) := "O611-HERB-BAN" if not zone in {"fence_line", "stem"}

# Rule O611-GEN-CONDITIONALITY: volle Förderung nur bei Einhaltung der Konditionalität
notices contains {"rule_id": "O611-GEN-CONDITIONALITY", "message": "Konditionalität nicht eingehalten: Kürzungen gemäß Art. 83 bis 89 VO (EU) 2021/2116"} if {
	participates
	object.get(input, ["farm", "oepul", "conditionality_compliant"], true) == false
}

# o6_11 policy module
# o6_11 – Zugangs- und Fördervoraussetzungen
#
#   Vertragszeitraum, Antragsfristen, Mindestteilnahmefläche,
#   Betriebsmindestgröße, förderwerbende Personen, Maßnahmenkombination.
package oepul.o6_11

# ---------------------------------------------------------------------------
# Vertragszeitraum (Rule O611-CONTRACT-PERIOD)
# ---------------------------------------------------------------------------
contract_period_row := row if {
	some row in cfg.contract_periods.rows
	row.start_year == contract_start_year
}

contract_end := cfg.contract_periods.contract_end

contract_years := contract_period_row.years

# Rule O611-CONTRACT-PERIOD: Beginn nur 2023, 2024 oder 2025 möglich
contract_start_valid if contract_period_row

# Rule O611-LAST-ENTRY: letzter Einstieg mit Förderjahr 2025
entry_after_last_entry_year if {
	participates
	contract_start_year > cfg.contract_periods.last_entry_year
}

# Rule O611-APPLY-DEADLINE: Beantragung im Maßnahmenantrag bis 31.12. vor Vertragsbeginn
application_deadline := sprintf("%d-12-31", [contract_start_year - 1])

application_in_time if {
	participates
	participation.application_date <= application_deadline
}

application_late if {
	participates
	participation.application_date
	not application_in_time
}

application_date_missing if {
	participates
	not participation.application_date
}

# Antragsjahr innerhalb des Vertragszeitraumes
year_in_contract_period if {
	contract_start_valid
	year >= contract_start_year
	year <= year_of(contract_end)
}

is_first_commitment_year if {
	contract_start_valid
	year == contract_start_year
}

# ---------------------------------------------------------------------------
# Mindestteilnahmefläche 0,5 ha im 1. Verpflichtungsjahr (Rule O611-MIN-AREA)
# ---------------------------------------------------------------------------
minimum_area_ha := sum([parcel_area(p) |
	some p in parcels
	counts_for_minimum_area(p)
])

minimum_area_met if minimum_area_ha >= cfg.contract_periods.first_year_minimum_area_ha

minimum_area_violation if {
	is_first_commitment_year
	not minimum_area_met
}

# ---------------------------------------------------------------------------
# Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (Rule O611-GEN-MIN-FARM-SIZE)
# ---------------------------------------------------------------------------
first_oepul_year := object.get(input, ["farm", "oepul", "first_participation_year"], contract_start_year)

farm_size_rule_applies if year == first_oepul_year

farm_min_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= cfg.general_conditions.farm_minimum_size.protected_cultivation_min_ha
}

farm_min_size_met if {
	object.get(input, ["land", "total_area_ha"], 0) >= cfg.general_conditions.farm_minimum_size.agricultural_area_min_ha
}

farm_min_size_violation if {
	farm_size_rule_applies
	not farm_min_size_met
}

# ---------------------------------------------------------------------------
# Förderwerbende Personen (Rules O611-GEN-APPLICANT-TYPE,
# O611-GEN-PUBLIC-BODY-EXCL, O611-GEN-ACTIVE-FARMER)
# ---------------------------------------------------------------------------
applicant := object.get(input, ["farm", "applicant"], {})

applicant_type_row := row if {
	some row in cfg.general_conditions.applicant_types
	row.legal_form == applicant.legal_form
}

public_body_exception_for_measure if {
	some row in cfg.general_conditions.public_body_exception_measures
	row.measure_id == measure_id
	year >= row.from_year
	year <= row.to_year
}

applicant_violations contains "unzulässige Rechtsform der förderwerbenden Person" if {
	applicant.legal_form
	not applicant_type_row
}

applicant_violations contains "Gebietskörperschaft bzw. deren Einrichtung ist für Maßnahme 11 nicht förderwerbend" if {
	applicant.is_public_body == true
	not public_body_exception_for_measure
}

applicant_violations contains "Beteiligung von Gebietskörperschaften über 25 %" if {
	applicant_type_row.max_public_body_share_percent != null
	object.get(applicant, "public_body_share_percent", 0) > applicant_type_row.max_public_body_share_percent
	not public_body_exception_for_measure
}

applicant_violations contains "kein aktiver Landwirt bzw. keine landwirtschaftliche Tätigkeit" if {
	applicant.is_active_farmer == false
}

applicant_violations contains "Betrieb nicht im eigenen Namen und auf eigene Rechnung bzw. ohne Verfügungsgewalt" if {
	applicant.farms_in_own_name_and_account == false
}

# ---------------------------------------------------------------------------
# Betriebliche Kombination mit „Biologische Wirtschaftsweise“ (Rule O611-COMB-BIO)
# ---------------------------------------------------------------------------
organic_participations := [m | some m in oepul_measures; m.measure_id == "1B"]

# Bio-Teilbetrieb ausschließlich mit Kulturbereich Acker und Grünland
organic_partial_arable_grassland_only(m) if {
	m.is_organic_partial_farm == true
	areas := {a | some a in m.organic_partial_culture_areas}
	areas == {"arable_grassland"}
}

# Betriebliche Ausschlüsse gemäß SRL 1.9.4 (data farm_combination_exclusions)
farm_exclusion_partners contains row.excluded_with if {
	some row in cfg.farm_combination_exclusions
	measure_id in row.measures
}

organic_combination_conflict if {
	participates
	"1B" in farm_exclusion_partners
	some m in organic_participations
	not organic_partial_arable_grassland_only(m)
	not converted_to_organic(m)
}

# Umstieg 11 -> 1B (Rule O611-SWITCH-BIO): die Bio-Teilnahme ersetzt Maßnahme 11
converted_to_organic(m) if {
	m.measure_id == "1B"
	participation.conversion_target == "1B"
}

# Rule O611-SWITCH-BIO: Umstieg in 1B nur bis spätestens 31.12.2025
switch_to_organic_allowed if {
	participation.conversion_target == "1B"
	participation.conversion_application_date <= cfg.contract_periods.switch_to_organic_deadline
	some row in cfg.measure_switch_table.rows
	row.from == measure_id
	"1B" in row.to
}

switch_to_organic_too_late if {
	participation.conversion_target == "1B"
	not switch_to_organic_allowed
}

# Jahr, ab dem Maßnahme 11 wegen Umstieg nicht mehr gilt (Folgejahr der Beantragung)
conversion_effective_year := year_of(participation.conversion_application_date) + 1 if switch_to_organic_allowed

converted_in_or_before_year if {
	switch_to_organic_allowed
	year >= conversion_effective_year
}

# ---------------------------------------------------------------------------
# Kombination auf der Einzelfläche gemäß Anhang L (Rule O611-COMB-PARCEL)
# ---------------------------------------------------------------------------
combination_cell(other) := cell if {
	some cell in cfg.combination_table.cells
	cell.row_measure == measure_id
	cell.column_measure == other
}

parcel_measures(p) := object.get(p, ["oepul", "measures"], [measure_id])

parcel_in_measure(p) if measure_id in parcel_measures(p)

parcel_combination_conflicts contains {"parcel_id": p.parcel_id, "other_measure": other} if {
	some p in parcels
	parcel_in_measure(p)
	some other in parcel_measures(p)
	other != measure_id
	not combination_cell(other)
}

# Fußnote 1): nur betreffend Abgeltung der Landschaftselemente kombinierbar
parcel_combination_limited contains {"parcel_id": p.parcel_id, "other_measure": other, "footnote": cell.footnote} if {
	some p in parcels
	parcel_in_measure(p)
	some other in parcel_measures(p)
	cell := combination_cell(other)
	cell.footnote != null
}

package oepul.o6_11_test

import data.oepul.o6_11

# ---------------------------------------------------------------------------
# Testdaten
# ---------------------------------------------------------------------------
applicant_ok := {
	"legal_form": "natural_person",
	"is_public_body": false,
	"public_body_share_percent": 0,
	"is_active_farmer": true,
	"farms_in_own_name_and_account": true,
}

m11(start) := {
	"measure_id": "11",
	"contract_start_year": start,
	"application_date": sprintf("%d-12-10", [start - 1]),
	"payment_claim_submitted": true,
}

vineyard(id, area) := {
	"parcel_id": id,
	"area_ha": area,
	"land_use": "special_crop",
	"crop": {"crop_category": "vineyard", "crop_name": null},
}

orchard(id, area, species) := {
	"parcel_id": id,
	"area_ha": area,
	"land_use": "special_crop",
	"crop": {"crop_category": "orchard", "crop_name": species, "is_grafted": true},
}

arable(id, area) := {
	"parcel_id": id,
	"area_ha": area,
	"land_use": "arable",
	"crop": {"crop_category": "cereal", "crop_name": "Weizen"},
}

farm_input(y, measures, parcel_list) := {
	"farm": {
		"year": y,
		"applicant": applicant_ok,
		"oepul": {"first_participation_year": 2023, "measures": measures},
	},
	"land": {"total_area_ha": 20, "parcels": parcel_list},
	"documentation": {"plant_protection_inventory": []},
}

with_parcel_field(parcel, key, value) := object.union(parcel, {key: value})

herbicide_app(date, zone) := {
	"date": date,
	"product_name": "Glyphosat-Produkt",
	"effect_type": "herbicide",
	"active_substances": ["Glyphosat"],
	"is_organic_approved": false,
	"is_area_wide": true,
	"application_zone": zone,
}

rule_ids(vs) := {v.rule_id | some v in vs}

# ---------------------------------------------------------------------------
# Prämie und Prämiensätze
# ---------------------------------------------------------------------------
test_premium_2026_wine_fruit_hop if {
	hop := {"parcel_id": "H1", "area_ha": 1, "land_use": "special_crop", "crop": {"crop_category": "hop", "crop_name": null}}
	inp := farm_input(2026, [m11(2023)], [vineyard("W1", 2), orchard("O1", 1, "Apfel"), hop])
	o6_11.parcel_premium == {"W1": 540, "O1": 270, "H1": 270} with input as inp
	o6_11.premium_payable == 1080 with input as inp
	o6_11.compliant with input as inp
}

test_premium_rate_2023_is_250 if {
	inp := farm_input(2023, [m11(2023)], [vineyard("W1", 1)])
	o6_11.parcel_premium.W1 == 250 with input as inp
}

test_premium_rate_from_2024_is_270 if {
	o6_11.premium_rate("obst", 2024) == 270
	o6_11.premium_rate("hopfen", 2028) == 270
	o6_11.premium_rate("wein", 2023) == 250
}

test_walnut_and_chestnut_no_premium_but_ban_applies if {
	inp := farm_input(2026, [m11(2023)], [orchard("O1", 1, "Walnuss"), orchard("O2", 1, "Edelkastanie"), vineyard("W1", 1)])
	not o6_11.parcel_premium.O1 with input as inp
	not o6_11.parcel_premium.O2 with input as inp
	o6_11.parcel_results.O1.herbicide_ban_applies with input as inp
}

test_fruit_species_from_2025 if {
	inp24 := farm_input(2024, [m11(2023)], [orchard("O1", 1, "Maulbeere"), vineyard("W1", 1)])
	not o6_11.parcel_results.O1.wine_fruit_hop_area with input as inp24
	inp25 := farm_input(2025, [m11(2023)], [orchard("O1", 1, "Maulbeere"), vineyard("W1", 1)])
	o6_11.parcel_results.O1.wine_fruit_hop_area with input as inp25
	o6_11.parcel_premium.O1 == 270 with input as inp25
}

test_other_wine_and_special_crop_no_premium if {
